class Obj(dict):
    """A dict whose keys also read as attributes, in either spelling:
    `res.matches[0].id`, `stats.total_vector_count` (== stats["totalVectorCount"])."""

    __slots__ = ()
    values = _Key("values", dict.values)

    def __getattr__(self, name: str) -> Any:
        if name in self:
